{
  "title": "Todo app",
  "summary": "Keep a list of tasks with a priority, a due date, and a done status, mark them as done, and filter by status.",
  "resources": [
    {
      "name": "todos",
      "fields": [
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "operations": ["list", "create", "update", "delete"]
    }
  ],
  "features": [
    "Form to add a task with title, description, priority, due date, and mark as done",
    "List of tasks showing every field, with a coloured priority badge",
    "Checkbox to mark a task as done",
    "Edit and Delete buttons on every task",
    "Filter the list by status (All, Open, Done)"
  ]
}

