{"thought":"The list_todos function is now implemented. I will move on to implementing the update_todo function, which will update a row and return it, or None if the id does not exist.","action":"implement","path":"database/todos.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE todos SET title = ?, description = ?, priority = ?, due_date = ?, done = ? WHERE id = ?", (title, description, priority, due_date, int(done), todo_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, title, description, priority, due_date, done FROM todos WHERE id = ?", (todo_id,)).fetchone()
    return dict(row)","function":"update_todo"}

{"thought":"All the functions are now implemented. I will write the tests for each function to ensure they work as expected.","action":"write_file","path":"tests/test_db_todos.py","content":"from database.todos import add_todo, list_todos, update_todo, delete_todo

import json


def test_add_returns_row():
    row = add_todo("a", "b", "High", "2023-10-01", False)
    assert row["title"] == "a" and "id" in row


def test_list_newest_first():
    add_todo("a", "b", "High", "2023-10-01", False)
    add_todo("c", "d", "Low", "2023-10-02", True)
    assert [n["title"] for n in list_todos()] == ["c", "a"]


def test_list_empty():
    assert list_todos() == []


def test_update_returns_updated_row():
    row = add_todo("a", "b", "High", "2023-10-01", False)
    updated_row = update_todo(row["id"], "new title", "new description", "Low", "2023-10-03", True)
    assert updated_row["title"] == "new title" and updated_row["id"] == row["id"]


def test_update_nonexistent_id():
    assert update_todo(999, "a", "b", "High", "2023-10-01", False) is None


def test_delete_returns_true_if_deleted():
    row = add_todo("a", "b", "High", "2023-10-01", False)
    assert delete_todo(row["id"]) is True


def test_delete_nonexistent_id():
    assert delete_todo(999) is False"}

